import re

with open("assets/core/index.js", "r") as f:
    text = f.read()

start = text.find("function CrowdCanvas({")
end = text.find("function renderPhoneMockup()")

old_crowd = """function CrowdCanvas({ src = "/assets/hero/hero-crowd-peeps.png", rows = 15, cols = 7, scale = 1 }) {  const canvasRef = (0, o.useRef)(null);  (0, o.useEffect)(() => {    const canvas = canvasRef.current;    if (!canvas) return;    const ctx = canvas.getContext("2d");    if (!ctx) return;    const gsap = window.gsap;    if (!gsap) return;    const config = { src, rows, cols };    const randomRange = (min, max) => min + Math.random() * (max - min);    const randomIndex = (array) => (randomRange(0, array.length) | 0);    const removeFromArray = (array, i) => array.splice(i, 1)[0];    const removeItemFromArray = (array, item) => removeFromArray(array, array.indexOf(item));    const removeRandomFromArray = (array) => removeFromArray(array, randomIndex(array));    const getRandomFromArray = (array) => array[randomIndex(array) | 0];    const resetPeep = ({ stage, peep }) => {      const direction = Math.random() > 0.5 ? 1 : -1;      const offsetY = (40 - 140 * (gsap.parseEase ? gsap.parseEase("power2.in")(Math.random()) : Math.random())) * scale;      const startY = stage.height - peep.height + offsetY;      let startX, endX;      if (direction === 1) {        startX = -peep.width;        endX = stage.width;        peep.scaleX = 1;      } else {        startX = stage.width + peep.width;        endX = 0;        peep.scaleX = -1;      }      peep.x = startX;      peep.y = startY;      peep.anchorY = startY;      return { startX, startY, endX };    };    const normalWalk = ({ peep, props }) => {      const { startX, startY, endX } = props;      const xDuration = 10;      const yDuration = 0.25;      const tl = gsap.timeline();      tl.timeScale(randomRange(0.5, 1.5));      tl.to(peep, { duration: xDuration, x: endX, ease: "none" }, 0);      tl.to(peep, { duration: yDuration, repeat: Math.floor(xDuration / yDuration), yoyo: true, y: startY - 10 * scale }, 0);      return tl;    };    const walks = [normalWalk];    const createPeep = ({ image, rect }) => {      const peep = {        image, rect: [], width: 0, height: 0, drawArgs: [], x: 0, y: 0, anchorY: 0, scaleX: 1, walk: null,        setRect: (r) => {          peep.rect = r;          peep.width = r[2] * scale;          peep.height = r[3] * scale;          peep.drawArgs = [peep.image, ...r, 0, 0, peep.width, peep.height];        },        render: (c) => {          c.save();          c.translate(peep.x, peep.y);          c.scale(peep.scaleX, 1);          c.drawImage(peep.image, peep.rect[0], peep.rect[1], peep.rect[2], peep.rect[3], 0, 0, peep.width, peep.height);          c.restore();        },      };      peep.setRect(rect);      return peep;    };    const img = document.createElement("img");    const stage = { width: 0, height: 0 };    const allPeeps = [];    const availablePeeps = [];    const crowd = [];    const createPeeps = () => {      const { rows, cols } = config;      const { naturalWidth: width, naturalHeight: height } = img;      const total = rows * cols;      const rectWidth = width / rows;      const rectHeight = height / cols;      for (let i = 0; i < total; i++) {        allPeeps.push(createPeep({ image: img, rect: [(i % rows) * rectWidth, ((i / rows) | 0) * rectHeight, rectWidth, rectHeight] }));      }    };    const addPeepToCrowd = () => {      if (!availablePeeps.length) return null;      const peep = removeRandomFromArray(availablePeeps);      const walk = getRandomFromArray(walks)({ peep, props: resetPeep({ peep, stage }) }).eventCallback("onComplete", () => {        removePeepFromCrowd(peep);        addPeepToCrowd();      });      peep.walk = walk;      crowd.push(peep);      crowd.sort((a, b) => a.anchorY - b.anchorY);      return peep;    };    const initCrowd = () => {      while (availablePeeps.length) {        const p = addPeepToCrowd();        if (p && p.walk) p.walk.progress(Math.random());      }    };    const removePeepFromCrowd = (peep) => {      removeItemFromArray(crowd, peep);      availablePeeps.push(peep);    };    const render = () => {      if (!canvas) return;      ctx.clearRect(0, 0, canvas.width, canvas.height);      ctx.save();      const dpr = window.devicePixelRatio || 1;      ctx.scale(dpr, dpr);      crowd.forEach((peep) => peep.render(ctx));      ctx.restore();    };    const resize = () => {      if (!canvas) return;      stage.width = canvas.clientWidth;      stage.height = canvas.clientHeight;      const dpr = window.devicePixelRatio || 1;      canvas.width = stage.width * dpr;      canvas.height = stage.height * dpr;      crowd.forEach((peep) => { if (peep.walk) peep.walk.kill(); });      crowd.length = 0;      availablePeeps.length = 0;      availablePeeps.push(...allPeeps);      initCrowd();    };    const init = () => {      createPeeps();      resize();      if (gsap && gsap.ticker) gsap.ticker.add(render);    };    img.onload = init;    img.src = config.src;    const handleResize = () => resize();    window.addEventListener("resize", handleResize);    return () => {      window.removeEventListener("resize", handleResize);      if (gsap && gsap.ticker) gsap.ticker.remove(render);      crowd.forEach((peep) => { if (peep.walk) peep.walk.kill(); });    };  }, []);  return (0, x.jsx)("canvas", {    ref: canvasRef,    style: { position: "absolute", bottom: 0, left: 0, width: "100%", height: "100%", pointerEvents: "none" }  });}
"""

text = text[:start] + old_crowd + text[end:]
with open("assets/core/index.js", "w") as f:
    f.write(text)
print("CrowdCanvas restored!")
